 /// 🪜️ Selects an original failure-storage birth before an ordinary close effect.
 pub fn requires_original_birth(&self)->bool{if !self.slots.terminal_is_empty(){self.slots.requires_original_birth()}else{self.retirement.requires_original_birth()}}
 /// 👶️ Advances the selected original failure-storage birth.
